CREATE TABLE IF NOT EXISTS patients (
  id              TEXT PRIMARY KEY,
  created_at      INTEGER NOT NULL,
  updated_at      INTEGER NOT NULL,
  given_name      TEXT NOT NULL,
  family_name     TEXT,
  contact_phone   TEXT,
  contact_email   TEXT,
  dob             TEXT,
  status          TEXT NOT NULL DEFAULT 'active'
);
CREATE INDEX IF NOT EXISTS idx_patients_status     ON patients(status);
CREATE INDEX IF NOT EXISTS idx_patients_updated_at ON patients(updated_at);

CREATE TABLE IF NOT EXISTS patient_lifecycle (
  patient_id       TEXT PRIMARY KEY REFERENCES patients(id),
  stage            TEXT NOT NULL,
  stage_updated_at INTEGER NOT NULL,
  stage_reason     TEXT
);
INSERT OR IGNORE INTO patient_lifecycle (patient_id, stage, stage_updated_at)
SELECT id, 'active', (strftime('%s','now') * 1000) FROM patients;

CREATE TABLE IF NOT EXISTS patient_risk_event (
  id             TEXT PRIMARY KEY,
  patient_id     TEXT NOT NULL REFERENCES patients(id),
  kind           TEXT NOT NULL,
  severity       TEXT,
  occurred_at    INTEGER NOT NULL,
  summary        TEXT,
  audit_event_id INTEGER
);
CREATE INDEX IF NOT EXISTS idx_risk_patient ON patient_risk_event(patient_id, occurred_at DESC);

CREATE TABLE IF NOT EXISTS patient_identity_alias (
  id           TEXT PRIMARY KEY,
  patient_id   TEXT NOT NULL REFERENCES patients(id),
  kind         TEXT NOT NULL,
  value_norm   TEXT NOT NULL,
  created_at   INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_alias_patient ON patient_identity_alias(patient_id);
CREATE INDEX IF NOT EXISTS idx_alias_lookup  ON patient_identity_alias(kind, value_norm);

CREATE TABLE IF NOT EXISTS participant_suppression (
  id_hash      TEXT PRIMARY KEY,
  kind         TEXT NOT NULL,
  created_at   INTEGER NOT NULL
);

CREATE TABLE participant_suppression_new (
  id_hash     TEXT NOT NULL,
  calendar_id TEXT NOT NULL DEFAULT '',
  kind        TEXT NOT NULL,
  created_at  INTEGER NOT NULL,
  PRIMARY KEY (id_hash, calendar_id)
);
INSERT INTO participant_suppression_new (id_hash, calendar_id, kind, created_at)
  SELECT id_hash, '', kind, created_at FROM participant_suppression;
DROP TABLE participant_suppression;
ALTER TABLE participant_suppression_new RENAME TO participant_suppression;
